import cv2
import numpy as np

def scene(shift):
    img = np.zeros((200, 200), np.uint8)
    for i in range(20, 160, 25):
        cv2.rectangle(img, (i + shift, i), (i + 15 + shift, i + 12), 200, -1)
    return img

orb = cv2.ORB_create(500)
kp1, des1 = orb.detectAndCompute(scene(0), None)
kp2, des2 = orb.detectAndCompute(scene(10), None)

good = []
if des1 is not None and des2 is not None and len(des2) >= 2:
    matcher = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=False)
    for pair in matcher.knnMatch(des1, des2, k=2):
        if len(pair) < 2:
            continue
        best, second = pair
        if best.distance < 0.75 * second.distance:
            good.append(best)

print(len(good))

