import cv2
import numpy as np
from contextlib import contextmanager

class Stopwatch:
    def __init__(self, window=120):
        self.samples = {}
        self.window = window

    @contextmanager
    def stage(self, name):
        start = cv2.getTickCount()
        try:
            yield
        finally:
            elapsed_ms = (cv2.getTickCount() - start) / cv2.getTickFrequency() * 1000.0
            bucket = self.samples.setdefault(name, [])
            bucket.append(elapsed_ms)
            if len(bucket) > self.window:
                del bucket[0]

    def report(self):
        out = {}
        for name, values in self.samples.items():
            arr = np.array(values)
            out[name] = (round(float(np.median(arr)), 2), round(float(np.percentile(arr, 95)), 2))
        return out

watch = Stopwatch()
frame = np.zeros((480, 640, 3), np.uint8)
for _ in range(10):
    with watch.stage("blur"):
        cv2.GaussianBlur(frame, (7, 7), 0)
    with watch.stage("hsv"):
        cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)

print(watch.report())

