import cv2
import numpy as np

marker_centers = {0: (100.0, 80.0), 1: (540.0, 84.0), 2: (536.0, 400.0), 3: (104.0, 396.0)}
table_mm = {0: (0.0, 0.0), 1: (400.0, 0.0), 2: (400.0, 300.0), 3: (0.0, 300.0)}

def workspace_transform(marker_centers, table_mm):
    ids = sorted(table_mm.keys())
    if any(i not in marker_centers for i in ids):
        return None
    src = np.float32([marker_centers[i] for i in ids])
    dst = np.float32([table_mm[i] for i in ids])
    return cv2.getPerspectiveTransform(src, dst)

def pixel_to_table(point, H):
    if H is None:
        return None
    p = np.float32([[[point[0], point[1]]]])
    mapped = cv2.perspectiveTransform(p, H)[0][0]
    return round(float(mapped[0]), 2), round(float(mapped[1]), 2)

H = workspace_transform(marker_centers, table_mm)
print(pixel_to_table((320.0, 240.0), H))

import cv2
import numpy as np


class Tracks:
    def __init__(self, confirm_hits=3, max_misses=5):
        self.items = {}
        self.next_id = 1
        self.confirm_hits = confirm_hits
        self.max_misses = max_misses

    def start(self, position):
        kf = cv2.KalmanFilter(4, 2)
        kf.transitionMatrix = np.array([
            [1, 0, 1, 0],
            [0, 1, 0, 1],
            [0, 0, 1, 0],
            [0, 0, 0, 1],
        ], np.float32)
        kf.measurementMatrix = np.array([
            [1, 0, 0, 0],
            [0, 1, 0, 0],
        ], np.float32)
        kf.processNoiseCov = np.eye(4, dtype=np.float32) * 1e-2
        kf.measurementNoiseCov = np.eye(2, dtype=np.float32) * 1e-1
        kf.statePost = np.array([[position[0]], [position[1]], [0.0], [0.0]], np.float32)
        kf.errorCovPost = np.eye(4, dtype=np.float32) * 10.0
        self.items[self.next_id] = {"kf": kf, "position": position, "hits": 1, "misses": 0}
        self.next_id += 1

    def update(self, detections, max_distance=40.0):
        for track in self.items.values():
            predicted = track["kf"].predict()
            track["position"] = (float(predicted[0][0]), float(predicted[1][0]))

        pairs = []
        for track_id, track in self.items.items():
            for index, detection in enumerate(detections):
                distance = float(np.hypot(
                    detection[0] - track["position"][0],
                    detection[1] - track["position"][1],
                ))
                if distance <= max_distance:
                    pairs.append((distance, track_id, index))

        pairs.sort()
        used_tracks = set()
        used_detections = set()
        for distance, track_id, index in pairs:
            if track_id in used_tracks or index in used_detections:
                continue
            track = self.items[track_id]
            corrected = track["kf"].correct(np.array(detections[index], np.float32).reshape(2, 1))
            track["position"] = (float(corrected[0][0]), float(corrected[1][0]))
            track["hits"] += 1
            track["misses"] = 0
            used_tracks.add(track_id)
            used_detections.add(index)

        for track_id, track in list(self.items.items()):
            if track_id not in used_tracks:
                track["misses"] += 1
                if track["misses"] > self.max_misses:
                    del self.items[track_id]

        for index, detection in enumerate(detections):
            if index not in used_detections:
                self.start(detection)

        return [
            (track_id, track["position"])
            for track_id, track in self.items.items()
            if track["hits"] >= self.confirm_hits
        ]


tracks = Tracks()
blind = (5, 6, 7)
worst = 0.0
reported = set()

for frame in range(18):
    truth = (40.0 + 15.0 * frame, 100.0)
    on_belt = frame < 12 and frame not in blind
    confirmed = tracks.update([truth] if on_belt else [])
    for track_id, position in confirmed:
        reported.add(track_id)
        if frame < 12:
            worst = max(worst, abs(position[0] - truth[0]))
    if frame in (2, 7, 8):
        label = {2: "confirmed", 7: "blind", 8: "back"}[frame]
        seen = [(track_id, round(position[0], 1)) for track_id, position in confirmed]
        print(label, "frame", frame, "truth", truth[0], "reported", seen)

print("worst error", round(worst, 1))
print("ids ever reported", sorted(reported))
print("live tracks at frame 17", len(tracks.items))

import cv2
import numpy as np

scene = {"fixed_camera": True, "controlled_light": True, "appearance_varies": False, "labelled_examples": 0}

def should_use_network(scene):
    if not scene.get("appearance_varies", False):
        return False, "appearance is describable, a classical gate is faster and inspectable"
    if scene.get("labelled_examples", 0) < 500:
        return False, "not enough labelled data, a network here would be guessing"
    if scene.get("fixed_camera") and scene.get("controlled_light"):
        return False, "scene is controlled, spend the effort on lighting instead"
    return True, "appearance varies beyond what thresholds can describe"

def run_onnx(net, crop, size=(224, 224)):
    blob = cv2.dnn.blobFromImage(crop, scalefactor=1 / 255.0, size=size, mean=(0, 0, 0), swapRB=True, crop=False)
    net.setInput(blob)
    return net.forward()

print(should_use_network(scene))
print(should_use_network({"fixed_camera": False, "controlled_light": False, "appearance_varies": True, "labelled_examples": 3000}))

