import cv2
import numpy as np

OPEN_KERNEL = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))

def bench_frame(markers=True, part=True):
    frame = np.full((480, 640, 3), 200, np.uint8)
    cv2.rectangle(frame, (150, 150), (269, 269), (50, 50, 50), -1)
    cv2.rectangle(frame, (370, 150), (489, 269), (50, 50, 50), -1)
    cv2.rectangle(frame, (150, 300), (489, 340), (90, 90, 90), -1)
    if markers:
        dictionary = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_4X4_50)
        for marker_id, (x, y) in zip(range(4), [(20, 20), (540, 20), (20, 380), (540, 380)]):
            frame[y - 10:y + 90, x - 10:x + 90] = 255
            tag = cv2.aruco.generateImageMarker(dictionary, marker_id, 80)
            frame[y:y + 80, x:x + 80] = cv2.cvtColor(tag, cv2.COLOR_GRAY2BGR)
    if part:
        cv2.rectangle(frame, (280, 200), (359, 279), (25, 150, 240), -1)
    return frame


class VisionNode:
    def __init__(self, min_focus=15.0, max_homography_age=90):
        self.state = "CALIBRATING"
        self.homography = None
        self.homography_age = 0
        self.min_focus = min_focus
        self.max_homography_age = max_homography_age
        self.part_lower = np.array([11, 114, 96], np.uint8)
        self.part_upper = np.array([23, 255, 255], np.uint8)

    def health(self, gray):
        return {
            "focus": round(float(cv2.Laplacian(gray, cv2.CV_64F).var()), 1),
            "exposure": round(float(gray.mean()), 1),
        }

    def find_markers(self, gray):
        dictionary = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_4X4_50)
        detector = cv2.aruco.ArucoDetector(dictionary, cv2.aruco.DetectorParameters())
        corners, ids, _ = detector.detectMarkers(gray)
        if ids is None:
            return {}
        return {int(i): tuple(c.reshape(-1, 2).mean(axis=0)) for i, c in zip(ids.ravel(), corners)}

    def find_parts(self, frame, min_area=400):
        hsv = cv2.cvtColor(cv2.GaussianBlur(frame, (5, 5), 0), cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(hsv, self.part_lower, self.part_upper)
        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, OPEN_KERNEL)
        count, _, stats, centroids = cv2.connectedComponentsWithStats(mask, connectivity=8)
        return [
            (round(float(centroids[i][0]), 1), round(float(centroids[i][1]), 1))
            for i in range(1, count)
            if stats[i, cv2.CC_STAT_AREA] >= min_area
        ]

    def step(self, frame):
        if frame is None or frame.size == 0:
            self.state = "FAULT"
            return {"state": self.state, "poses": [], "reason": "no frame from camera"}

        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        health = self.health(gray)

        if health["focus"] < self.min_focus or health["exposure"] < 10.0:
            self.state = "FAULT"
            return {"state": self.state, "poses": [], "reason": "camera health check failed", "health": health}

        markers = self.find_markers(gray)
        if len(markers) >= 4:
            self.homography = markers
            self.homography_age = 0
        else:
            self.homography_age += 1

        if self.homography is None:
            self.state = "CALIBRATING"
            return {"state": self.state, "poses": [], "reason": "waiting for four workspace markers", "health": health}

        if self.homography_age > self.max_homography_age:
            self.state = "FAULT"
            self.homography = None
            return {"state": self.state, "poses": [], "reason": "workspace markers lost", "health": health}

        poses = self.find_parts(frame)
        if not poses:
            self.state = "DEGRADED"
            return {"state": self.state, "poses": [], "reason": "no parts detected, hold position", "health": health}

        self.state = "RUNNING"
        return {"state": self.state, "poses": poses, "reason": None, "health": health}


node = VisionNode()
for frame in (bench_frame(markers=False), bench_frame(), bench_frame(part=False), None):
    result = node.step(frame)
    print(result["state"], result["poses"], result["reason"])
